mapper.select:
select 
from repro_events e
where e.house_id = #{houseId}
  and e.batch_id = #{batchId}
  and e.event_type in ('DELIVERY_DONE', 'DELIVERY_FAILED')
order by e.occurred_at desc, e.id desc
limit #{limit}

select 
from repro_events e
where e.house_id = #{houseId}
  and e.mother_rabbit_id = #{rabbitId}
  and e.event_type in ('DELIVERY_DONE', 'DELIVERY_FAILED')
order by e.occurred_at desc, e.id desc
limit #{limit}

select 
from repro_events e
where e.house_id = #{houseId}
  and e.batch_id = #{batchId}
  and e.event_type in ('PALPATION_PREGNANT', 'PALPATION_EMPTY', 'PALPATION_UNSURE')
order by e.occurred_at desc, e.id desc
limit #{limit}

select 
from repro_events e
where e.house_id = #{houseId}
  and e.mother_rabbit_id = #{rabbitId}
  and e.event_type in ('PALPATION_PREGNANT', 'PALPATION_EMPTY', 'PALPATION_UNSURE')
order by e.occurred_at desc, e.id desc
limit #{limit}
